package br.com.bora.entity; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.OffsetDateTime; @Entity @Getter @Setter public class Pedido{@Id @GeneratedValue(strategy=GenerationType.IDENTITY) public Long id; public Long lojaId; public String codigo; public Long clienteId; @Enumerated(EnumType.STRING) public StatusPedido status=StatusPedido.RECEBIDO; public BigDecimal valorTotal; public String formaPagamento; public String origem; public String observacao; public OffsetDateTime criadoEm=OffsetDateTime.now(); public OffsetDateTime atualizadoEm=OffsetDateTime.now(); public OffsetDateTime entregueEm; public OffsetDateTime canceladoEm; public String motivoCancelamento; public String entregador; @Column(name="canal_externo") public String canalExterno; @Column(name="id_externo") public String idExterno; @Column(name="taxa_entrega") public BigDecimal taxaEntrega=BigDecimal.ZERO; /** Item 5.8: quem entregou. true = o marketplace, e ficou com a `taxaEntrega`; false = a loja; null = nao se aplica (balcao, cardapio) ou pedido anterior a V58. Nulo NAO e false: false afirma que a loja recebeu a taxa. O FATURAMENTO nao olha esta coluna -- `valorTotal` continua sendo o bruto que o cliente pagou. Descontar a taxa muda um numero que o dono olha todo dia, e e decisao dele; o que esta coluna da e ver o tamanho, no `taxaDoMarketplace` do RelatorioService. */ @Column(name="entrega_pelo_canal") public Boolean entregaPeloCanal; @Column(name="cliente_telefone") public String clienteTelefone; @Column(name="acerto_id") public Long acertoId; /** PIX online gerado e ainda nao pago. Pedido de balcao, WhatsApp ou marketplace nasce false. */ @Column(name="aguardando_pagamento") public Boolean aguardandoPagamento=false; /** Endereco informado NESTE pedido. O card do painel mostrava `cliente.endereco`, que no cliente recorrente e o endereco ANTIGO: entregar no lugar errado era questao de ele ter se mudado. Ver V48. */ @Column(name="endereco_entrega") public String enderecoEntrega; /** Bairro escolhido NESTE pedido, o que define o frete. Antes nao era gravado em lugar nenhum, e "entregas por bairro" jogava todo pedido do canal proprio em "Sem bairro". */ @Column(name="bairro_entrega") public String bairroEntrega; /** ENTREGA ou RETIRADA. Era so o texto "RETIRADA NO BALCAO" na observacao, e a tela de Entregas oferecia "Despachar" para quem ia buscar na loja. Nulo = pedido anterior a V48. */ @Column(name="tipo_entrega") public String tipoEntrega; /** Quando o marketplace ACEITOU o aceite automatico. Nulo com autoAceitar ligado significa que ha aceite a reenviar: sem esta marca, o aceite que falhava se perdia para sempre (o pedido continua RECEBIDO aqui, aceito ou nao). */ @Column(name="aceite_enviado_em") public OffsetDateTime aceiteEnviadoEm; /** Quanto de cashback o cliente abateu neste pedido. Sem guardar isto, o desconto saia do total e o saldo nunca era debitado no PIX: o mesmo cashback valia em quantos pedidos o cliente quisesse. */ @Column(name="cashback_usado", precision=12, scale=2) public BigDecimal cashbackUsado; /** Quando o pagamento online foi confirmado pelo Asaas. */ @Column(name="pago_em") public OffsetDateTime pagoEm; /** O dinheiro desta venda ja entrou? Pedido que espera PIX ainda nao e faturamento. */ /** E retirada no balcao? Le a coluna; pedido anterior a V48 cai na deducao antiga pelo texto. */ public boolean ehRetirada(){ if(tipoEntrega!=null) return "RETIRADA".equalsIgnoreCase(tipoEntrega); return observacao!=null && observacao.toUpperCase().contains("RETIRADA NO BALC"); } public boolean pagamentoPendente(){ return Boolean.TRUE.equals(aguardandoPagamento) && pagoEm==null; }}
